Aquí te dejo una función en C++ que convierte texto en formato Markdown a HTML:

```cpp
#include <iostream>
#include <string>
#include <regex>

// Función para convertir texto de formato Markdown a HTML
std::string convertMarkdownToHtml(const std::string& markdown) {
    std::string html;

    // Reemplazar tildes por acentos en texto Markdown
    markdown = replaceTildeWithAccent(markdown);

    // Reemplazar formato de texto
    std::regex regex_text("\\*(.*?)\\*|_(.*?)_|~?(.*?)~?");
    std::smatch match;
    while (std::regex_search(markdown, match, regex_text)) {
        std::string text = match[1].str() + match[2].str() + match[3].str();
        html += "<strong>" + text + "</strong>";
        markdown = match.prefix();
    }

    // Reemplazar formato de enlaces
    std::regex regex_link("\\[(.*?)\\]\\((.*?)\\)");
    while (std::regex_search(markdown, match, regex_link)) {
        std::string link_text = match[1].str();
        std::string link_url = match[2].str();
        html += "<a href=\"" + link_url + "\">" + link_text + "</a>";
        markdown = match.prefix();
    }

    // Reemplazar formato de listas
    std::regex regex_list_item("^(\\s+)?-(\\s+)?(\\*|\\d+\\.?\\s?)(\\s+)?(.*?)$");
    while (std::regex_search(markdown, match, regex_list_item)) {
        std::string text = match[5].str();
        std::string list_item;
        if (match[2].str() == "*") {
            list_item = "<li>" + text + "</li>";
        } else {
            list_item = "<li>" + match[2].str() + ". " + text + "</li>";
        }
        if (!match.prefix().empty()) {
            html += "<ul>\n" + list_item + "\n</ul>\n";
        } else {
            html += list_item;
        }
        markdown = match.suffix();
    }

    // Reemplazar formato de citas
    std::regex regex_quote(">( .*? )");
    while (std::regex_search(markdown, match, regex_quote)) {
        std::string text = match[1].str();
        html += "<blockquote>" + text + "</blockquote>\n";
        markdown = match.suffix();
    }

    // Reemplazar formato de código
    std::regex regex_code("```(.*?)\\n(.*?)\\n```");
    while (std::regex_search(markdown, match, regex_code)) {
        std::string language = match[1].str();
        std::string code = match[2].str();
        html += "<pre><code class=\"" + language + "\">" + code + "</code></pre>\n";
        markdown = match.suffix();
    }

    // Agregar etiquetas HTML restantes
    html = "<html><head><meta charset=\"UTF-8\"></head><body>" + markdown + "</body></html>";

    return html;
}

// Función auxiliar para reemplazar tildes por acentos
std::string replaceTildeWithAccent(const std::string& str) {
    std::string result = str;
    std::replace(result.begin(), result.end(), '~', 'ñ');
    return result;
}

int main() {
    std::string markdown = "Este es un *texto* en **bold**. ¡Mira el enlace! [Google](https://www.google.com/). - Lista 1\n- Lista 2\n> Esta es una cita. ```cpp\n#include <iostream>\nint main() {\n    std::cout << \"Hola mundo\" << std::endl;\n    return 0;\n}\n```";

    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Esta función usa expresiones regulares para reemplazar los formatos de texto, enlaces, listas, citas y código en el texto Markdown. También agrega etiquetas HTML básicas para el encabezado y el cuerpo del documento.

La función `replaceTildeWithAccent` es una función auxiliar para reemplazar las tildes por acentos en el texto Markdown, ya que en el formato HTML se utilizan acentos. 

El ejemplo de uso en el `main` convierte el texto Markdown proporcionado en el formato HTML. 

